#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>

#include <stddef.h>
#include <stdlib.h>
typedef struct SNode { int value; struct SNode *next; } SNode;
void s_reverse(SNode **head);
int s_middle(const SNode *head);
int s_is_sorted(const SNode *head);
void s_remove_all(SNode **head, int v);
/* support helpers provided (implement only the four above) */
static void s_push(SNode **head, int v) { SNode *n = malloc(sizeof *n); if (!n) return; n->value = v; n->next = *head; *head = n; }
static size_t s_len(const SNode *head) { size_t n = 0; for (const SNode *p = head; p; p = p->next) n++; return n; }
static void s_clear(SNode **head) { SNode *cur = *head; while (cur) { SNode *nx = cur->next; free(cur); cur = nx; } *head = NULL; }

