SNode *head = NULL;
for (int i = 1; i <= 5; i++) s_push(&head, i);   /* 5 4 3 2 1 */
s_reverse(&head);
/* now 1 2 3 4 5 */
CHECK(head->value == 1);
CHECK(head->next->value == 2);
CHECK(head->next->next->next->next->value == 5);
CHECK_EQ(s_middle(head), 3);
CHECK_EQ(s_is_sorted(head), 1);
s_remove_all(&head, 3);
CHECK_EQ(s_len(head) == 0 ? 0 : head->value, 1);  /* survived */
/* rebuild: 5 3 3 1 */
