s_push(&h2, 1); s_push(&h2, 3); s_push(&h2, 3); s_push(&h2, 5);
s_remove_all(&h2, 3);
CHECK_EQ(s_len(h2), 2);
CHECK(h2->value == 5 && h2->next->value == 1);
s_clear(&h2);
